"""Authenticated HTTPS API client. Password stays in process memory only."""
import json
from pathlib import Path
import subprocess

import requests

ROOT = Path(__file__).resolve().parents[1]


class ProductsClient:
    def __init__(self):
        config = json.loads((ROOT / '.state/config.json').read_text())
        self.endpoint = (ROOT / '.state/endpoint.txt').read_text().strip()
        if not self.endpoint.startswith('https://'):
            raise ValueError('Refusing to send workshop credentials over plaintext HTTP')
        password = subprocess.check_output(['az', 'keyvault', 'secret', 'show', '--subscription', config['subscription'],
                    '--vault-name', config['stem'] + '-kv', '--name', 'products-password', '--query', 'value', '-o', 'tsv'], text=True).strip()
        self.session = requests.Session()
        self.session.auth = ('participant', password)
        self.session.verify = str(ROOT / '.state/tls.crt')
        csrf = self.get('/api/csrf')
        self.session.headers[csrf['headerName']] = csrf['token']

    def call(self, method, path, **kwargs):
        response = self.session.request(method, self.endpoint + path, timeout=(10, 30), **kwargs)
        if response.status_code >= 400:
            raise RuntimeError(f'Products HTTP {response.status_code} for {path}. Check sign-in, source CIDR, CSRF and server logs.')
        return response.json()

    def get(self, path):
        return self.call('GET', path)

    def ask(self, question, product=None):
        return self.call('POST', '/api/questions', json={'question': question, 'productId': product})

    def upload(self, path, name):
        with path.open('rb') as manual:
            return self.call('POST', '/api/products', data={'name': name}, files={'manual': (path.name, manual, 'text/plain')})

"""Generate ARM parameters from one validated config; secrets stay ephemeral."""
import json
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]
config = json.loads((ROOT / '.state/config.json').read_text())
stage = sys.argv[1]
keys = {
    'models': ['location', 'chatModel', 'chatVersion', 'chatCapacity', 'embeddingModel', 'embeddingVersion', 'embeddingCapacity', 'modelSku'],
    'foundation': ['location', 'stem'],
    'database': ['location', 'stem', 'postgresSku'],
    'compute': ['location', 'stem', 'aksVmSize', 'aksNodes'],
}[stage]
values = {key: {'value': config[key]} for key in keys}
if stage == 'models':
    values['name'] = {'value': config['stem'] + '-ai'}
if stage in ('models', 'foundation'):
    values['operatorId'] = {'value': sys.argv[2]}
if stage == 'database':
    secret = subprocess.check_output(['az', 'keyvault', 'secret', 'show', '--subscription', config['subscription'],
              '--vault-name', config['stem'] + '-kv', '--name', 'postgres-password', '--query', 'value', '-o', 'tsv'], text=True).strip()
    values['pgPassword'] = {'value': secret}
path = ROOT / f'.state/{stage}.parameters.json'
path.write_text(json.dumps({'$schema': 'https://schema.management.azure.com/schemas/2019-04-01/deploymentParameters.json#',
                            'contentVersion': '1.0.0.0', 'parameters': values}))
path.chmod(0o600)

"""Locate separate app checkouts; cloning runs only when explicitly requested."""
import argparse
import json
import os
from pathlib import Path
import subprocess

WORKSHOP = Path(__file__).resolve().parents[1]


def repositories():
    return json.loads((WORKSHOP / 'repositories.json').read_text(encoding='utf-8'))


def application_dir(name, *, require=True):
    entry = repositories()[name]
    parent = Path(os.environ.get('AI200_APPS_DIR', WORKSHOP.parent.parent)).expanduser().resolve()
    path = parent / entry['directory']
    if require and not (path / '.git').exists():
        raise RuntimeError(f'Missing {entry["name"]} checkout: {path}. Run bash workshop/scripts/get-apps.sh.')
    return path


def git(path, *args):
    result = subprocess.run(['git', '-c', 'safe.directory=' + path.as_posix(), '-C', str(path), *args], text=True, capture_output=True, timeout=180)
    if result.returncode:
        raise RuntimeError(f'Git failed for {path.name}: {result.stderr[-1200:]}')
    return result.stdout.strip()


def clone():
    for name, entry in repositories().items():
        path = application_dir(name, require=False)
        if path.exists():
            if not (path / '.git').exists():
                raise RuntimeError(f'Refusing to overwrite existing non-repository directory: {path}')
            if git(path, 'remote', 'get-url', 'origin').removesuffix('.git') != entry['url'].removesuffix('.git'):
                raise RuntimeError(f'Origin differs for {path}; keep your checkout and choose AI200_APPS_DIR explicitly.')
            head = git(path, 'rev-parse', 'HEAD')
            if entry['ref'] != 'main' and head != entry['ref']:
                raise RuntimeError(f'{path} is at {head}, expected {entry["ref"]}. Commit local work and select the workshop revision explicitly.')
            print(f'Reusing {path}; local work is preserved.')
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        result = subprocess.run(['git','clone','--no-checkout',entry['url'],str(path)], timeout=180)
        if result.returncode:
            raise RuntimeError(f'Clone failed for {entry["url"]}; check access/network and retry.')
        git(path, 'checkout', '--detach', entry['ref'])
        print(f'Prepared {path}')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['clone','path'])
    parser.add_argument('name', nargs='?', choices=['products','embedder','chat'])
    args = parser.parse_args()
    try:
        if args.action == 'clone':
            clone()
        elif args.name:
            print(application_dir(args.name))
        else:
            parser.error('path requires an application name')
    except (OSError, RuntimeError, subprocess.TimeoutExpired) as error:
        parser.exit(1, str(error) + '\n')
